function validate([coins, maxJump]) {
  if (!Array.isArray(coins) || coins.length < 1 || coins.length > 1000) return 'coins needs 1 to 1000 values.';
  if (coins.some(v => !Number.isInteger(v) || v < -1 || v > 100)) return 'Each coin is an integer from -1 to 100.';
  if (coins[0] === -1) return 'The first position cannot be blocked (-1).';
  if (!Number.isInteger(maxJump) || maxJump < 1 || maxJump > 100) return 'maxJump is between 1 and 100.';
  return null;
}

