function cheapestJump(coins, maxJump) {
  const n = coins.length;
  const cost = new Array(n).fill(Infinity);
  const next = new Array(n).fill(-1);
  if (coins[n - 1] === -1) {
    return [];
  }
  cost[n - 1] = coins[n - 1];

  for (let i = n - 2; i >= 0; i--) {
    if (coins[i] === -1) {
      continue;
    }
    const last = Math.min(i + maxJump, n - 1);
    for (let j = i + 1; j <= last; j++) {
      if (coins[i] + cost[j] < cost[i]) {
        cost[i] = coins[i] + cost[j];
        next[i] = j;
      }
    }
  }

  if (cost[0] === Infinity) {
    return [];
  }
  const path = [];
  for (let i = 0; i !== -1; i = next[i]) {
    path.push(i + 1);
  }
  return path;
}

