function cheapestJump(coins, maxJump) {
  // Forward DP over whole routes: best[j] is the cheapest, then lexicographically smallest, route from position 1 to j.
  const n = coins.length;
  const better = (a, costA, b, costB) => {
    if (costA !== costB) return costA < costB;
    for (let t = 0; t < Math.min(a.length, b.length); t++) if (a[t] !== b[t]) return a[t] < b[t];
    return a.length < b.length;
  };
  const best = new Array(n).fill(null);
  const total = new Array(n).fill(Infinity);
  best[0] = [1];
  total[0] = coins[0];
  for (let j = 1; j < n; j++) {
    if (coins[j] === -1) continue;
    for (let i = Math.max(0, j - maxJump); i < j; i++) {
      if (best[i] === null) continue;
      const route = [...best[i], j + 1];
      const spent = total[i] + coins[j];
      if (best[j] === null || better(route, spent, best[j], total[j])) {
        best[j] = route;
        total[j] = spent;
      }
    }
  }
  return best[n - 1] ?? [];
}

