function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 10);
  const maxJump = size === 'large' ? 1 + Math.floor(rand() * 100) : 1 + Math.floor(rand() * 5);
  const top = size === 'large' ? (rand() < 0.5 ? 100 : 3) : 1 + Math.floor(rand() * 4);
  const blocked = size === 'large' ? rand() * 0.15 : rand() * 0.4;
  const coins = Array.from({ length: n }, () => rand() < blocked ? -1 : Math.floor(rand() * (top + 1)));
  if (coins[0] === -1) coins[0] = Math.floor(rand() * (top + 1));
  return [coins, maxJump];
}
